def read_user_login_time(username=None):
    if username is None:
        file_path = login_txt_base_url + 'last_login_time.txt'
    else:
        file_path = login_txt_base_url + username + '/last_login_time.txt'
    rfile = None
    rtime = -1
    try:
        if os.path.exists(file_path):
            rfile = open(file_path, 'r')
            data = rfile.read()
            if data != '':
                rtime = int(float(data.split()[-1]))
            rfile.close()
        return rtime
        return None
    except BaseException as ex:
        if rfile is not None:
            rfile.close()
        app_log.info('【read_user_login_time】获取最新登录时间，发生错误')
        app_log.info(ex)
